sys_script_include.script:
function BusinessProcessGetMermaidState(business_process,strDirection)
{
	if (BusinessProcessValidate(business_process,false) == false)
	{
		return false;
	}
	strDirection = GetStringValue(strDirection);

	var strCode = '---\n';
	strCode += 'title: ' + JSON.stringify(String(business_process.name)) + '\n';
	strCode += '---\n';
	strCode += 'stateDiagram-v2\n';

	if (strDirection != '')
	{
		strCode += 'direction ' + strDirection + '\n';
	}

	var aStates = business_process._states;
	var aTransitions = business_process._transitions;
	var transitions = {};

	for (var nState = 0; nState < aStates.length; nState++)
	{
		var state = aStates[nState];
		var strName = String(state.name).replace(/[\r\n]+/g,' ').replace(/"/g,'#quot;');
		strCode += '\tstate "' + strName + '" as ' + state.id + '\n';
	}

	for (var nTransition = 0; nTransition < aTransitions.length; nTransition++)
	{
		var transition = aTransitions[nTransition];
		transitions['$' + transition.id] = transition;
	}

	strCode += '\t[*] --> ' + business_process.initial_state + '\n';

	for (var nSource = 0; nSource < aStates.length; nSource++)
	{
		var source = aStates[nSource];
		for (var nLink = 0; nLink < source._transitions.length; nLink++)
		{
			var link = transitions['$' + source._transitions[nLink]];
			var strLabel = String(link.label).replace(/[\r\n]+/g,' ');
			strCode += '\t' + source.id + ' --> ' + link.target_state + ' : ' + strLabel + '\n';
		}
	}

	var aEndStates = business_process.end_states;
	for (var nEnd = 0; nEnd < aEndStates.length; nEnd++)
	{
		strCode += '\t' + aEndStates[nEnd] + ' --> [*]\n';
	}

	return strCode;
}
